"""Word list parser and Hunspell writer. No Sublime Text imports.

Word list format:

    # comment
    btw
    repo/S          `/S` adds a plural: repo, repos
    GitHub          mixed case also adds the lowercase form: github
"""

AFF = """\
# Generated by DevDictionary. Do not edit.
SET UTF-8
TRY esianrtolcdugmphbyfvkwzESIANRTOLCDUGMPHBYFVKWZ
WORDCHARS 0123456789

SFX S Y 4
SFX S   y     ies        [^aeiou]y
SFX S   0     s          [aeiou]y
SFX S   0     es         [sxzh]
SFX S   0     s          [^sxzhy]
"""

FLAGS = "S"


def parse(text):
    """Return {word: flags} for one word list."""
    entries = {}
    for line in text.splitlines():
        for token in line.split("#", 1)[0].split():
            word, _, flags = token.partition("/")
            if not word:
                continue
            flags = "".join(f for f in FLAGS if f in flags)
            for form in (word, word.lower()):
                entries[form] = merge_flags(entries.get(form, ""), flags)
    return entries


def merge_flags(a, b):
    return "".join(f for f in FLAGS if f in a or f in b)


def merge(*lists):
    """Merge several {word: flags} dicts into one."""
    entries = {}
    for item in lists:
        for word, flags in item.items():
            entries[word] = merge_flags(entries.get(word, ""), flags)
    return entries


def plural(word):
    """Apply the `SFX S` rule from AFF."""
    if word.endswith("y") and word[-2:-1] not in ("a", "e", "i", "o", "u"):
        return word[:-1] + "ies"
    if word[-1:] in ("s", "x", "z", "h"):
        return word + "es"
    return word + "s"


def expand(entries):
    """Return every word form that the Hunspell files accept."""
    words = set(entries)
    words.update(plural(w) for w, flags in entries.items() if "S" in flags)
    return words


def render_dic(entries):
    lines = sorted(w + "/" + f if f else w for w, f in entries.items())
    return "{}\n{}\n".format(len(lines), "\n".join(lines))
